package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen0Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    @Test
    public void testGetTextBuffer_SharedInputBuffer() {
        char[] sharedBuf = {'a', 'b', 'c'};
        // Trigger: if (_inputStart >= 0) return _inputBuffer;
        textBuffer.resetWithShared(sharedBuf, 0, 3);

        char[] result = textBuffer.getTextBuffer();
        assertSame("Should return the shared input buffer", sharedBuf, result);
    }

    @Test
    public void testGetTextBuffer_ResultArray() {
        // Trigger: if (_resultArray != null) return _resultArray;
        // We can achieve this by appending and finishing a segment, 
        // or by using resetWithCopy which populates the internal array.
        char[] input = {'x', 'y', 'z'};
        textBuffer.resetWithCopy(input, 0, 3);

        // In TextBuffer, resetWithCopy populates the internal non-segmented array
        char[] resultBefore = textBuffer.getTextBuffer();
        assertArrayEquals(input, resultBefore);

        // Call again to ensure it returns the same cached _resultArray
        char[] resultAfter = textBuffer.getTextBuffer();
        assertSame("Should return the cached _resultArray", resultBefore, resultAfter);
    }

    @Test
    public void testGetTextBuffer_ResultString() {
        // Trigger: if (_resultString != null) { return (_resultArray = _resultString.toCharArray()); }
        String str = "hello";
        textBuffer.resetWithString(str);

        char[] result = textBuffer.getTextBuffer();
        assertArrayEquals(str.toCharArray(), result);

        // Verify that _resultArray was cached by calling again
        char[] result2 = textBuffer.getTextBuffer();
        assertSame("Should return the newly created _resultArray from the string", result, result2);
    }

    @Test
    public void testGetTextBuffer_CurrentSegment() {
        // Trigger: if (!_hasSegments && true) return _currentSegment;
        // This happens when the buffer is fresh and has no shared input, no result array, and no result string.
        // Note: In Jackson's TextBuffer, a new buffer starts with _hasSegments = false.

        // We ensure it's in the "segment" state by not calling resetWithShared/Copy/String
        char[] result = textBuffer.getTextBuffer();

        // Since it's a new buffer, it should return the initial segment
        // We can't easily assert the exact array instance of the internal segment without reflection, 
        // but we can check it's not null and behaves like a segment.
        assertNotNull(result);
    }

    @Test
    public void testGetTextBuffer_ContentsAsArray() {
        // Trigger: return contentsAsArray();
        // This branch is reached if _hasSegments becomes true (i.e., we have multiple segments).

        textBuffer.append('a');
        textBuffer.append('b');
        // Force creation of multiple segments
        textBuffer.finishCurrentSegment();
        textBuffer.append('c');

        // Once _hasSegments is true, the logic falls through to contentsAsArray()
        // if the other conditions aren't met.
        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        // Since we finished a segment and added more, it must be a non-segmented array
        // We check the content to verify correctness
        String content = textBuffer.contentsAsString();
        assertEquals("abc", content);
        assertArrayEquals(content.toCharArray(), result);
    }
}
